#!/bin/bash
# fix keyframes after QA (CLI, ~2cr each)
cd "$(dirname "$0")/.."
ST="Claymation stop-motion film still, Aardman-like plasticine with fingerprint texture, miniature handmade clay Korean neighborhood diorama, soft warm light. Cars have a face only on the windshield. No text, no letters, no words anywhere."
gen(){ id=$1; ar=$2; refs=""; for r in $3; do refs="$refs --image-references $r"; done
  ( url=$(higgsfield generate create nano_banana_flash --prompt "$4" $refs --aspect_ratio $ar --resolution 2k --wait 2>&1 | grep -o 'https://[^ ]*\.png' | tail -1)
    [ -n "$url" ] && curl -s -o "keyframes_fix/$id.png" "$url" && echo "$id ok" || echo "$id FAIL" ) & }
gen A04 16:9 "keyframes_ad/A04.png" "Edit this image. Keep everything identical (camera, framing, the round 30 speed sign, the yellow child-zone sign, the red road, the blurred clay street, lighting, clay style) but add, on the same pole just below the child sign, a second yellow pentagon warning sign showing a simple pictogram of an elderly person walking with a cane. No letters anywhere except the number 30."
gen A11 16:9 "chars/grandma.png chars/boy.png chars/turtle.png" "$ST Cinematic 16:9 medium-wide shot. The grandmother (reference) and the boy (reference) have finished crossing and stand on the far sidewalk; the grandmother bows her head politely in thanks and the boy waves. In the foreground the green turtle-car (reference, turtle shell roof) is stopped BEHIND the thick white stop line, clearly before the zebra crosswalk (the crosswalk stripes lie between the car and the sidewalk), and it winks back kindly. Red school-zone road, golden light."
gen A14 16:9 "" "$ST Cinematic 16:9 medium shot of a Korean young woman in her twenties (college student, short bob hair, mint hoodie, jeans, small backpack) riding alone on an electric kick scooter in a clearly marked bicycle lane at the edge of a clay road; she wears a bright yellow bicycle helmet with the chin strap fastened and taps the helmet proudly with one hand, big confident smile. Cherry-blossom clay tree and cozy clay houses behind, warm light."
gen A17 16:9 "keyframes_ad/A17.png" "Edit this image. Keep everything exactly the same (composition, cars, children, school building, lighting, clay style) but remove all lettering from the school building sign and any other sign: blank clay signboards only. Absolutely no letters anywhere."
gen A21 16:9 "keyframes_ad/A21.png" "Edit this image. Keep everything exactly the same (composition, children crossing, turtle-shell cars, crosswalk, school, lighting, clay style) but remove the word painted on the road surface in front of the cars: keep only the plain thick white stop line. Absolutely no letters anywhere."
gen S05 9:16 "keyframes/S05.png" "Edit this image. Keep everything exactly the same (composition, the row of turtle-shell cars, grandmother, boy, street, lighting, clay style) except: the mascot no longer holds an octagonal stop sign; instead it holds up a small bright yellow traffic-safety flag in one hand and gives a thumbs up with the other. Remove any octagonal STOP sign from the scene. No letters anywhere."
gen S09 9:16 "" "$ST Vertical 9:16 medium shot of a Korean young woman in her twenties (college student, short bob hair, mint hoodie, jeans, small backpack) riding alone on an electric kick scooter in a clearly marked bicycle lane at the edge of a clay road; she wears a bright yellow bicycle helmet with the chin strap fastened and taps the helmet proudly with one hand, big confident smile. Cherry-blossom clay tree and cozy clay houses behind, warm light."
gen S10 9:16 "chars/rabbit.png" "$ST Vertical 9:16 shot on a red-painted clay Korean school-zone road: the red rabbit-car (reference) speeds forward and gets caught by a realistic Korean fixed speed enforcement camera: a tall slim grey steel pole with a long horizontal arm over the road, a white rectangular camera housing with a dark glass lens window facing traffic mounted on the arm, and a separate small square flash unit beside it firing a bright white flash. The rabbit-car's ears droop in shock, eyes wide, mouth open. Comedic."
wait
